// R1-T3 authored overhead rigs (D-057): string lights, lanterns, bunting, laundry lines and the bazaar vault, as SVG.
// Writes art/arenas/overhead/<theme>-<rig>-<variant>.svg (review copies) and js/view/arena-overhead-data.js (what the game loads;
// SVG as strings, so it works from file://). Sources: tools/arena-overhead/{rigs,hoods}.js. Usage: node prototype/tools/gen-arena-overhead.js
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', '..');
const hoods = require('./arena-overhead/hoods.js');
const dir = path.join(ROOT, 'art', 'arenas', 'overhead'); fs.mkdirSync(dir, { recursive: true });
fs.readdirSync(dir).filter(n => n.endsWith('.svg')).forEach(n => fs.unlinkSync(path.join(dir, n)));
const data = {}, report = [];
Object.keys(hoods).forEach(id => {
  data[id] = {};
  Object.keys(hoods[id]).forEach(kind => {
    data[id][kind] = hoods[id][kind].map((r, v) => {
      fs.writeFileSync(path.join(dir, id + '-' + kind + '-' + v + '.svg'), r.svg);
      return { w: r.w, h: r.h, ax: r.ax, ay: r.ay, alpha: r.alpha, glows: r.glows.map(g => [+g[0].toFixed(3), +g[1].toFixed(3), g[2], g[3]]), svg: r.svg };
    });
  });
  report.push(id + '[' + Object.keys(hoods[id]).join(',') + ']');
});
const out = '// GENERATED by tools/gen-arena-overhead.js (R1-T3, D-057). Do not edit by hand. Source: art/arenas/overhead/*.svg.\n' +
  'P.ArenaOverheadData = ' + JSON.stringify(data) + ';\n';
fs.writeFileSync(path.join(ROOT, 'prototype', 'js', 'view', 'arena-overhead-data.js'), out);
console.log('arena overhead: ' + report.join(' ') + ', ' + (out.length / 1024).toFixed(0) + ' KB');
